18	    stdout += `${args.join(" ")}\n`;
19	  };
20	  console.error = (...args: unknown[]) => {
21	    stderr += `${args.join(" ")}\n`;
22	  };
23	  try {
24	    const code = await fn();
25	    return { code, stdout, stderr };
